-- 項目 1b：OFFICIAL_OMITS_REAL_CARD 7 張標 jp-search-omitted（printings、cards 各 7）
do $$
declare n int;
begin
  update public.tcg_printings p set metadata = p.metadata || jsonb_build_object('officialListing','jp-search-omitted','officialListingCheckedAt','2026-10-14','officialListingEvidence','docs/evidence/audit-20261014/pokemon-jp-pending-spotcheck.json')
  where p.region='JP' and p.source='tcgdex-ja' and p.card_id = any(array['pokemon-tcgdex-ja-s5i-084','pokemon-tcgdex-ja-s5i-085','pokemon-tcgdex-ja-s6h-084','pokemon-tcgdex-ja-s6h-085','pokemon-tcgdex-ja-s6k-084','pokemon-tcgdex-ja-s6k-085','pokemon-tcgdex-ja-s6k-086']) and p.metadata->>'officialListing' is distinct from 'jp-search-omitted';
  get diagnostics n = row_count; if n <> 7 then raise exception '項目 1b：OFFICIAL_OMITS_REAL_CARD 7 張標 jp-search-omitted（printings、cards 各 7）: % rows, expected 7', n; end if;
  update public.tcg_cards c set metadata = c.metadata || jsonb_build_object('officialListing','jp-search-omitted')
  where c.source='tcgdex-ja' and c.id = any(array['pokemon-tcgdex-ja-s5i-084','pokemon-tcgdex-ja-s5i-085','pokemon-tcgdex-ja-s6h-084','pokemon-tcgdex-ja-s6h-085','pokemon-tcgdex-ja-s6k-084','pokemon-tcgdex-ja-s6k-085','pokemon-tcgdex-ja-s6k-086']) and c.metadata->>'officialListing' is distinct from 'jp-search-omitted';
  get diagnostics n = row_count; if n <> 7 then raise exception '項目 1b：OFFICIAL_OMITS_REAL_CARD 7 張標 jp-search-omitted（printings、cards 各 7）: % rows, expected 7', n; end if;
end
$$;

-- 項目 2：SM12a 184／197 以官方資料覆蓋（cards、printings、canonical、images 各 2）
do $$
declare n int;
begin
  with v(card_id, official_id, new_ja, old_ja, old_zh) as (values ('pokemon-tcgdex-ja-sm12a-184','37452','メルメタルGX','ルカリオ&メルメタルGX',null), ('pokemon-tcgdex-ja-sm12a-197','37465','ホミカ','ホミカの演奏','霍米加的演奏'))
  update public.tcg_cards c set name_ja = v.new_ja, name_zh = null, rarity = 'SR', rarity_tier = 7, data_status = 'verified',
    aliases = array_append(array_remove(array_remove(c.aliases, v.old_ja), v.old_zh), v.new_ja),
    search_text = replace(c.search_text, v.old_ja, v.new_ja),
    metadata = (c.metadata - 'nameZhBasis' - 'nameZhRule' - 'nameZhSourceCardId') || jsonb_strip_nulls(jsonb_build_object(
      'nameJaBefore', v.old_ja, 'nameJaBasis', 'pokemon-card.com 官方詳細頁 ' || v.official_id || '（TCGdex 封存的名稱與稀有度和官方同號卡抵觸，ADR 0040）',
      'nameZhBefore', v.old_zh, 'nameZhBeforeBasis', case when v.old_zh is null then null else c.metadata->>'nameZhBasis' end,
      'officialCardIds', jsonb_build_array(v.official_id))),
    updated_at = now()
  from v where c.id = v.card_id and c.name_ja = v.old_ja and c.rarity = 'UR' and c.data_status = 'pending';
  get diagnostics n = row_count; if n <> 2 then raise exception '項目 2：SM12a 184／197 以官方資料覆蓋（cards、printings、canonical、images 各 2）: % rows, expected 2', n; end if;
  with v(card_id, official_id, new_ja, old_ja, old_zh) as (values ('pokemon-tcgdex-ja-sm12a-184','37452','メルメタルGX','ルカリオ&メルメタルGX',null), ('pokemon-tcgdex-ja-sm12a-197','37465','ホミカ','ホミカの演奏','霍米加的演奏'))
  update public.tcg_printings p set rarity = 'SR', rarity_code = 'SR', rarity_label = 'SR', data_status = 'verified',
    metadata = p.metadata || jsonb_build_object('rarityBasis', 'pokemon-card-official-jp', 'officialCardId', v.official_id,
      'rarityBeforeOfficial', jsonb_build_object('rarity', p.rarity, 'basis', coalesce(p.metadata->>'rarityBasis', p.source))),
    updated_at = now()
  from v where p.card_id = v.card_id and p.region = 'JP' and p.source = 'tcgdex-ja' and p.rarity_code = 'UR' and p.data_status = 'pending';
  get diagnostics n = row_count; if n <> 2 then raise exception '項目 2：SM12a 184／197 以官方資料覆蓋（cards、printings、canonical、images 各 2）: % rows, expected 2', n; end if;
  with v(card_id, official_id, new_ja, old_ja, old_zh) as (values ('pokemon-tcgdex-ja-sm12a-184','37452','メルメタルGX','ルカリオ&メルメタルGX',null), ('pokemon-tcgdex-ja-sm12a-197','37465','ホミカ','ホミカの演奏','霍米加的演奏'))
  update public.tcg_canonical_cards cc set name_ja = v.new_ja, name_zh = case when cc.name_zh = v.old_zh then null else cc.name_zh end,
    aliases = (select array_agg(distinct a order by a) from unnest(array_remove(array_remove(cc.aliases, v.old_ja), v.old_zh) || array[v.new_ja]) a), updated_at = now()
  from v where cc.id = v.card_id and cc.name_ja = v.old_ja;
  get diagnostics n = row_count; if n <> 2 then raise exception '項目 2：SM12a 184／197 以官方資料覆蓋（cards、printings、canonical、images 各 2）: % rows, expected 2', n; end if;
  insert into public.card_images (card_id, canonical_id, language, source, image_url, source_url, is_primary, image_rights_status, rights_note)
  select c.id, c.canonical_id, 'ja-JP', 'pokemon-card-official-jp', v.image_url, v.source_url, true, 'not-provided', 'ADR 0031'
  from (values ('pokemon-tcgdex-ja-sm12a-184','https://www.pokemon-card.com/assets/images/card_images/large/SM12a/037452_P_MERUMETARUGX.jpg','https://www.pokemon-card.com/card-search/details.php/card/37452/regu/all'), ('pokemon-tcgdex-ja-sm12a-197','https://www.pokemon-card.com/assets/images/card_images/large/SM12a/037465_T_HOMIKA.jpg','https://www.pokemon-card.com/card-search/details.php/card/37465/regu/all')) v(card_id, image_url, source_url)
  join public.tcg_cards c on c.id = v.card_id
  where not exists (select 1 from public.card_images i where i.card_id = v.card_id);
  get diagnostics n = row_count; if n <> 2 then raise exception '項目 2：SM12a 184／197 以官方資料覆蓋（cards、printings、canonical、images 各 2）: % rows, expected 2', n; end if;
end
$$;

-- 項目 3a：Prism Star 3 張稀有度改官方值（printings、cards 各 3）
do $$
declare n int;
begin
  with v(card_id, official_id) as (values ('pokemon-tcgdex-ja-sm5p-037','34600'), ('pokemon-tcgdex-ja-sm5p-048','34611'), ('pokemon-tcgdex-ja-sm6a-050','34842'))
  update public.tcg_printings p set rarity = 'Rare Prism Star', rarity_code = 'Rare Prism Star', rarity_label = 'Rare Prism Star',
    metadata = p.metadata || jsonb_build_object('rarityBasis', 'pokemon-card-official-jp', 'officialCardId', v.official_id,
      'rarityBeforeOfficial', jsonb_build_object('rarity', p.rarity, 'basis', coalesce(p.metadata->>'rarityBasis', p.source))),
    updated_at = now()
  from v where p.card_id = v.card_id and p.region = 'JP' and p.source = 'tcgdex-ja' and p.rarity_code = 'Rare Holo';
  get diagnostics n = row_count; if n <> 3 then raise exception '項目 3a：Prism Star 3 張稀有度改官方值（printings、cards 各 3）: % rows, expected 3', n; end if;
  with v(card_id, official_id) as (values ('pokemon-tcgdex-ja-sm5p-037','34600'), ('pokemon-tcgdex-ja-sm5p-048','34611'), ('pokemon-tcgdex-ja-sm6a-050','34842'))
  update public.tcg_cards c set rarity = 'Rare Prism Star', updated_at = now()
  from v where c.id = v.card_id and c.rarity = 'Rare Holo';
